import React, { useState } from "react";
import classNames from "classnames";
import { Room } from "matrix-js-sdk/src/models/room";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import MatrixClientContext from "../../../contexts/MatrixClientContext";
import { usePermalink, PillType } from "../../../hooks/usePermalink";
import Tooltip, { Alignment } from "./Tooltip";

export { PillType };

export interface PillProps {
    type?: PillType;
    url?: string;
    inMessage?: boolean;
    room?: Room;
    shouldShowPillAvatar?: boolean;
}

export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

export function pillRoomNotifLen(): number {
    return "@room".length;
}

export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ url, type, room });
    const [hovered, setHovered] = useState(false);

    if (text === null || resolvedType === null) return null;

    const client = MatrixClientPeg.get();
    const pillClasses = classNames("mx_Pill", {
        mx_UserPill: resolvedType === PillType.UserMention,
        mx_RoomPill: resolvedType === PillType.RoomMention,
        mx_AtRoomPill: resolvedType === PillType.AtRoomMention,
        mx_SpacePill: resolvedType === "space",
        mx_UserPill_me: resolvedType === PillType.UserMention && resourceId === client.getUserId(),
    });
    const tooltip = hovered && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;
    const content = (
        <>
            {shouldShowPillAvatar === true ? avatar : null}
            <span className="mx_Pill_linkText">{text}</span>
            {tooltip}
        </>
    );
    const isLink = inMessage === true && Boolean(url) && resolvedType !== PillType.AtRoomMention;

    return (
        <bdi>
            <MatrixClientContext.Provider value={client}>
                {isLink ? (
                    <a
                        className={pillClasses}
                        href={url}
                        onClick={resolvedType === PillType.UserMention ? onClick : undefined}
                        onMouseOver={() => setHovered(true)}
                        onMouseLeave={() => setHovered(false)}
                    >
                        {content}
                    </a>
                ) : (
                    <span
                        className={pillClasses}
                        onMouseOver={() => setHovered(true)}
                        onMouseLeave={() => setHovered(false)}
                    >
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
}

